import base64
import json
import os
import runpy
import subprocess
import sys
from pathlib import Path
from huggingface_hub import snapshot_download

RUN_LOG = Path("/kaggle/working/kronos_small_0_1_stage2_oos/run.log")


def emit(message):
    RUN_LOG.parent.mkdir(parents=True, exist_ok=True)
    line = str(message)
    with RUN_LOG.open("a", buffering=1) as handle:
        handle.write(line + "\n")
    print(line, flush=True)


def find_one(root, pattern):
    matches = list(root.glob(pattern))
    if len(matches) != 1:
        raise RuntimeError(f"Expected one {pattern}, found {len(matches)}: {matches}")
    return matches[0]


input_root = Path("/kaggle/input")
os.environ["PYTHONUNBUFFERED"] = "1"
emit("phase=discover_inputs")
notebook_root = Path("/kaggle/input/notebooks")
model_candidates = [
    path for path in notebook_root.glob("**/model/__init__.py")
    if "kaggle_v1_beta_minimal" not in str(path)
]
if len(model_candidates) != 1:
    raise RuntimeError(f"Expected one primary model source, found {len(model_candidates)}: {model_candidates}")
source_root = model_candidates[0].parent.parent
sys.path.insert(0, str(source_root))
sys.path.insert(0, str(source_root / "finetune"))

gpu_name = subprocess.run(
    ["nvidia-smi", "--query-gpu=name", "--format=csv,noheader"],
    capture_output=True, text=True, check=False,
).stdout.strip()
if "P100" not in gpu_name:
    raise RuntimeError(f"Expected P100, got {gpu_name}")
arch_check = subprocess.run(
    [sys.executable, "-c", "import torch; raise SystemExit(0 if 'sm_60' in torch.cuda.get_arch_list() else 1)"],
    check=False,
)
if arch_check.returncode:
    emit("phase=install_p100_torch")
    subprocess.run(
        [sys.executable, "-m", "pip", "install", "-q", "--index-url", "https://download.pytorch.org/whl/cu121", "torch==2.5.1"],
        check=True,
    )

# The sealed dataset now exposes the matured OOS package at the dataset root
# (evaluation_manifest.json/evaluation_panel.pkl/evaluation_samples.jsonl).
# Keep the old nested package as a fallback for reproducibility.
evaluation_roots = list(input_root.glob("**/evaluation_manifest.json"))
evaluation_root = None
for manifest_path in evaluation_roots:
    candidate = manifest_path.parent
    if (candidate / "evaluation_panel.pkl").is_file() and (candidate / "evaluation_samples.jsonl").is_file():
        try:
            manifest = json.loads(manifest_path.read_text())
        except Exception:
            continue
        isolation = manifest.get("temporal_isolation", {})
        if isolation.get("incremental_signal_start"):
            evaluation_root = candidate
            break
if evaluation_root is None:
    evaluation_root = find_one(input_root, "**/kronos_small_0_1_time_oos_evaluation_20260826/evaluation")
emit(f"phase=download_base_model evaluation_root={evaluation_root}")
c2_best_model = find_one(notebook_root, "**/small_0.1_stage2_cosine_refinement/checkpoints/best_model")
c2_last_model = find_one(notebook_root, "**/small_0.1_stage2_cosine_refinement/checkpoints/last_model")
tokenizer = find_one(notebook_root, "**/Kronos-Tokenizer-base")
output_dir = Path("/kaggle/working/kronos_small_0_1_stage2_oos")
base_model = Path(snapshot_download("NeoQuasar/Kronos-small", local_dir="/kaggle/working/Kronos-small"))
emit(f"phase=base_model_ready path={base_model}")

evaluator_path = Path("/kaggle/working/evaluate_small_0_1_oos.py")
evaluator_path.write_bytes(base64.b64decode(""))
sys.argv = [
    "evaluate_small_0_1_oos.py",
    "--evaluation-root", str(evaluation_root),
    "--tokenizer", str(tokenizer),
    "--best-model", str(c2_best_model),
    "--last-model", str(c2_last_model),
    "--base-model", str(base_model),
    "--output-dir", str(output_dir),
    "--batch-size", "64",
]
runpy.run_path(str(evaluator_path), run_name="__main__")
emit("phase=evaluator_finished")

required = [output_dir / "summary.json", output_dir / "predictions.csv.gz"]
missing = [str(path) for path in required if not path.is_file()]
if missing:
    raise RuntimeError(json.dumps({"missing_outputs": missing}))
print(json.dumps({"status": "complete", "output_dir": str(output_dir)}), flush=True)
